const SLOT_STEP=10, SLOT_COIN={pct:.3,min:100}, SLOT_STAR={stars:99,n:10,max:200}, VIP_CAP=500, VIP_SLOTS=[0,VIP_CAP,VIP_CAP,VIP_CAP];
